mapper.select:
SELECT id, title, content, user_id as userId, category, is_important as isImportant, is_popup as isPopup, view_count as viewCount, DATE_FORMAT(publish_date, '%Y-%m-%d %H:%i:%s') as publishDate, DATE_FORMAT(expire_date, '%Y-%m-%d %H:%i:%s') as expireDate, is_active as isActive, DATE_FORMAT(created_at, '%Y-%m-%d %H:%i:%s') as createdAt, DATE_FORMAT(updated_at, '%Y-%m-%d %H:%i:%s') as updatedAt FROM notices WHERE is_active = true
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
AND category = #{category}
ORDER BY created_at DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*) FROM notices WHERE is_active = true
AND (title LIKE CONCAT('%', #{search}, '%') OR content LIKE CONCAT('%', #{search}, '%'))
AND category = #{category}
